// Normalize Input and Classify Intent, Persona & Language
const body = $input.first().json.body || {};
const type = body.type || 'voice';
const rawLang = (body.active_language || 'en').toLowerCase();

let text = '';
if (body.text) {
  text = body.text;
} else if (body.query) {
  text = body.query;
} else if (body.messages && body.messages.length > 0) {
  const lastMsg = body.messages[body.messages.length - 1];
  text = lastMsg.content || '';
}

const t = text.toLowerCase().trim();

// Determine Persona: Lisa or Jarvis
let persona = body.persona || 'Jarvis';
if (t.includes('lisa') || t.includes('hey lisa') || t.includes('hi lisa')) {
  persona = 'Lisa';
} else if (t.includes('jarvis') || t.includes('hey jarvis') || t.includes('hi jarvis')) {
  persona = 'Jarvis';
}

const LANG_CONFIG = {
  'kn': { name: 'Kannada', native: 'ಕನ್ನಡ', confirm: 'ಆಯ್ತು, ಇನ್ನು ಮುಂದೆ ನಾನು ಕನ್ನಡದಲ್ಲಿ ಉತ್ತರಿಸುತ್ತೇನೆ.' },
  'hi': { name: 'Hindi', native: 'हिंदी', confirm: 'नमस्ते! अब मैं हिंदी में बात करूँगा।' },
  'ta': { name: 'Tamil', native: 'தமிழ்', confirm: 'சரி, இனி நான் தமிழில் பேசுகிறேன்.' },
  'te': { name: 'Telugu', native: 'తెలుగు', confirm: 'సరే, ఇకనుండి నేను తెలుగులో మాట్లాడతాను.' },
  'ml': { name: 'Malayalam', native: 'മലയാളം', confirm: 'ശരി, ഇനി ഞാൻ മലയാളത്തിൽ സംസാരിക്കാം.' },
  'mr': { name: 'Marathi', native: 'मराठी', confirm: 'ठीक आहे, आता मी मराठीत बोलेन.' },
  'bn': { name: 'Bengali', native: 'বাংলা', confirm: 'ঠিক আছে, এখন থেকে আমি বাংলায় কথা বলব.' },
  'en': { name: 'English', native: 'English', confirm: "Sure, I'll speak in English from now on." }
};

const LANG_DETECTORS = {
  'te': [
    'telugu', 'telegu', 'telgu',
    'ತೆಲುಗು', 'ತೆಲುಗಿನಲ್ಲಿ', 'ತೆಲುಗಿಗೆ', 'ತೆಲುಗುಗೆ', 'ತೆಲುಗು ಭಾಷೆ',
    'తెలుగు', 'తెలుగులో', 'తెలుగుకి', 'తెలుగు మాట్లాడు', 'తెలుగు భాష',
    'तेलुगु', 'तेलगु', 'तेलुगू', 'तेलुगु में',
    'தெலுங்கு', 'தெலுங்கில்'
  ],
  'kn': [
    'kannada', 'kannad', 'kanada',
    'ಕನ್ನಡ', 'ಕನ್ನಡದಲ್ಲಿ', 'ಕನ್ನಡಕ್ಕೆ', 'ಕನ್ನಡ ಮಾತನಾಡು', 'ಕನ್ನಡ ಭಾಷೆ',
    'కన్నడ', 'కన్నడంలో', 'కన్నడ మాట్లాడు', 'కన్నడకి', 'కన్నడ భాష',
    'कन्नड़', 'कन्नड', 'कन्नड़ा', 'कन्नड़ में',
    'கன்னடம்', 'கன்னடத்தில்'
  ],
  'hi': [
    'hindi', 'hind',
    'ಹಿಂದಿ', 'ಹಿಂದಿಯಲ್ಲಿ', 'ಹಿಂದಿಗೆ', 'ಹಿಂದಿ ಮಾತನಾಡು',
    'ಹಿಂದೀ', 'ಹಿಂದೀಲೋ', 'హిందీ', 'హిందీలో', 'హిందీ మాట్లాడు', 'హిందీకి',
    'हिंदी', 'हिन्दी', 'हिंदी में', 'हिंदी बोलो',
    'இந்தி', 'ஹிந்தி'
  ],
  'ta': [
    'tamil', 'thamizh', 'tamizh',
    'ತಮಿಳು', 'ತಮಿಳಿನಲ್ಲಿ', 'ತಮಿಳಿಗೆ', 'ತಮಿಳು ಮಾತನಾಡು', 'ತಮಿಳ್',
    'తమిళం', 'తమిళంలో', 'తమిళం మాట్లాడు', 'తమిళ్', 'తమిళ',
    'तमिल', 'तमिल में',
    'தமிழ்', 'தமிழில்', 'தமிழுக்கு', 'தமிழ் பேசு'
  ],
  'en': [
    'english', 'angrezi', 'angreji', 'inglish',
    'ಇಂಗ್ಲಿಷ್', 'ಇಂಗ್ಲೀಷ್', 'ಇಂಗ್ಲಿಶ್', 'ಇಂಗ್ಲಿಷ್ನಲ್ಲಿ', 'ಇಂಗ್ಲಿಷ್ಗೆ', 'ಇಂಗ್ಲಿಷ್ ಮಾತನಾಡು', 'ಆಂಗ್ಲ', 'ಆಂಗ್ಲದಲ್ಲಿ',
    'ఇంగ్లీష్', 'ఇంగ్లిష్', 'ఇంగ్లీషు', 'ఇంగ్లిషు', 'ఇంగ్లీష్ లో', 'ఇంగ్లిష్ లో', 'ఆంగ్లం', 'ఆంగ్లంలో',
    'अंग्रेजी', 'अंग्रेज़ी', 'इंग्लिश', 'इंगरेजी', 'अंग्रेजी में',
    'ஆங்கிலம்', 'இங்கிலீஷ்', 'இங்கிலிஷ்'
  ],
  'ml': ['malayalam', 'ಮಲಯಾಳಂ', 'మలయాళం', 'मलयालम', 'മലയാളം'],
  'mr': ['marathi', 'ಮರಾಠಿ', 'ಮರಾಠೀ', 'मराठी'],
  'bn': ['bengali', 'bangla', 'ಬೆಂಗಾಲಿ', 'ಬಂಗಾಳಿ', 'బెಂಗಾಲೀ', 'बंगाली', 'বাংলা']
};

let intent = 'GENERAL_QUERY';
let targetLang = rawLang;
let payload = {};

// 1. Cross-Script Language Detection
const switchActions = [
  'switch', 'change', 'speak', 'talk', 'language', 'convert', 'turn', 'in', 'to', 'communicate', 'need you', 'can you', 'with',
  'ಸ್ವಿಚ್', 'ಬದಲಾಯಿಸು', 'ಬದಲಾಯಿಸಿ', 'ಮಾತನಾಡು', 'ಮಾತನಾಡಿ', 'ಕಮ್ಯುನಿಕೇಟ್', 'ಭಾಷೆ', 'ನಲ್ಲಿ',
  'స్విచ్', 'మార్చు', 'మార్చండి', 'మాట్లాడు', 'మాట్లాడండి', 'కమ్యూనికేట్', 'భాష', 'లో', 'కాన్ యూ', 'నీడ్',
  'स्विच', 'बदलो', 'बदलें', 'बोलो', 'बोलिए', 'बात करो', 'बात करें', 'कम्युनिकेट', 'भाषा', 'में',
  'சுவிட்ச்', 'மாற்று', 'மாத்து', 'பேசு', 'பேசுங்கள்', 'மொழி', 'இல்'
];
const hasAction = switchActions.some(act => t.includes(act));

const isMusicToken = ['play', 'song', 'songs', 'music', 'ಹಾಡು', 'ಹಾಡುಗಳು', 'ಪ್ಲೇ', 'ಸಾಂಗ್', 'ಸಾಂಗ್ಸ್', 'పాట', 'పాటలు', 'గానా', 'गाना', 'गाने', 'பாடல்', 'பாட்டு'].some(k => t.includes(k));
if (!isMusicToken) {
  for (const [code, keywords] of Object.entries(LANG_DETECTORS)) {
  for (const kw of keywords) {
    if (t.includes(kw)) {
      if (hasAction || t.split(/\s+/).length <= 5) {
        intent = 'LANGUAGE_SWITCH';
        targetLang = code;
        payload.active_language = code;
        payload.answer = LANG_CONFIG[code]?.confirm || 'Language switched!';
        break;
      }
    }
  }
  if (intent === 'LANGUAGE_SWITCH') break;
  }
}

// 2. Stop / Interruption
if (intent === 'GENERAL_QUERY' && (t === 'stop' || t === 'wait' || t === 'cancel' || t === 'enough' || t === 'shut up' || t === 'stop music')) {
  intent = 'STOP';
}

// 3. Ambiguity Check: "How will/would I look in [x]?"
if (intent === 'GENERAL_QUERY' && (t.startsWith('how would i look in') || t.startsWith('how will i look in') || t.startsWith('how do i look in'))) {
  intent = 'IMAGE_AMBIGUOUS';
  const item = text.replace(/how (?:would|will|do) i look in/i, '').trim();
  payload.subject = item;
  payload.answer = `Would you like me to generate a realistic image of you in ${item}, or would you like a style recommendation?`;
}

// 4. Universal Image Generation
const imgTriggers = ['generate', 'create an image', 'create image', 'make an image', 'draw', 'picture of', 'image of', 'show image', 'show an image'];
if (intent === 'GENERAL_QUERY' && imgTriggers.some(w => t.includes(w)) && !t.includes('recommend') && !t.includes('how would i look in')) {
  intent = 'IMAGE_GENERATE';
  const item = text.replace(/^(?:can\s+you\s+)?(?:please\s+)?(?:generate|create|draw|make|show(?:\s+me)?)\s+(?:an?\s+)?(?:image\s+(?:of\s+)?|picture\s+(?:of\s+)?|photo\s+(?:of\s+)?)?/i, '')
                   .replace(/^(?:generate|create|draw|make|show)\s+(?:the\s+|a\s+|an\s+)?/i, '')
                   .trim() || 'a cute cat';
  payload.subject = item;
  payload.enhanced_prompt = `candid raw 35mm photograph of a real ${item}, authentic natural lighting, real skin texture, natural realism, unedited photo`;
  payload.image_url = `https://image.pollinations.ai/prompt/${encodeURIComponent(payload.enhanced_prompt)}?width=768&height=768&model=flux&nologo=true`;
  payload.answer = `Sure, generating an image of ${item}!`;
}

// 5. Universal Multilingual Music Request (Kannada, Telugu, Hindi, Tamil, English)
const musicTriggers = [
  'play', 'put on', 'listen to', 'song', 'songs', 'music', 'hits', 'track', 'tracks',
  'ಹಾಡು', 'ಹಾಡುಗಳು', 'ಪ್ಲೇ', 'ಸಾಂಗ್', 'ಸಾಂಗ್ಸ್', 'ಸಂಗೀತ', 'ಹಾಕು', 'ಕೇಳಿಸು', 'ಗಾನಾ', 'ಮಾಡಿಸು',
  'పాట', 'పాటలు', 'ప్లే', 'సాంగ్', 'సాಂಗ್స్', 'సంగీతం', 'మ్యూజిక్', 'వినిపించు', 'పెట్టు', 'గానా',
  'गाना', 'गाने', 'गीत', 'सॉन्ग', 'प्ले', 'बजाओ', 'सुनाओ', 'चलाओ', 'लगाओ', 'म्यूजिक', 'संगीत',
  'பாடல்', 'பாட்டு', 'பாடல்கள்', 'பிளே', 'சாங்', 'போடு', 'இசை',
  'പാട്ട്', 'ഗാനം'
];

if (intent === 'GENERAL_QUERY' && musicTriggers.some(w => t.includes(w)) && !t.includes('game') && !t.includes('with me')) {
  intent = 'MUSIC_PLAY';
  let songQuery = text.replace(/[.,!?।]/g, ' ').replace(/\s+/g, ' ').trim();
  songQuery = songQuery
    .replace(/^(?:dude,?\s*)?(?:can\s+you\s+)?(?:please\s+)?(?:play|put\s+on|listen\s+to|start|i\s+want(?:\s+to\s+listen\s+to)?)\s+(?:some\s+)?(?:songs?\s+|music\s+|track\s+)?(?:of\s+|by\s+)?/i, '')
    .replace(/^(?:some\s+)?(?:songs?\s+|music\s+)?(?:of\s+|by\s+)?/i, '')
    .replace(/\s+(?:songs?|music|track)$/i, '')
    .replace(/(?:ನ\s+)?(?:ಪ್ಲೇ\s+ಮಾಡು|ಪ್ಲೇ\s+ಮಾಡಿ|ಹಾಡು\s+ಹಾಕು|ಹಾಕು|ಕೇಳಿಸು|ಪ್ಲೇ|ಮಾಡು)$/i, '')
    .replace(/^(?:ದಯವಿಟ್ಟು\s+)?(?:ಯಾವುದಾದರೂ\s+)?(?:ಹಾಡು\s+|ಸಾಂಗ್\s+)?/i, '')
    .replace(/(?:ಸಾಂಗ್ಸ್?|ಹಾಡುಗಳು?)$/i, '')
    .replace(/\s+(?:ನ|ನಲ್ಲಿ)$/i, '')
    .replace(/(?:ಪ್ಲೇ\s+చేయి|ಪ್ಲೇ\s+చేయండి|వినిపించు|పెట్టు|ప్ಲೇ|చేయి)$/i, '')
    .replace(/(?:పాటలు?|సాಂಗ್స్?)$/i, '')
    .replace(/(?:बजाओ|सुनाओ|चलाओ|लगाओ|प्ले)$/i, '')
    .replace(/(?:गाने?|गीत|सॉन्ग)$/i, '')
    .trim();

  const langDefaults = {
    'te': 'Telugu hits',
    'kn': 'Kannada hits',
    'hi': 'Bollywood Hindi hits',
    'ta': 'Tamil hits',
    'ml': 'Malayalam hits',
    'mr': 'Marathi hits',
    'bn': 'Bengali hits',
    'en': 'top trending hits'
  };

  const genericWords = [
    'music', 'song', 'songs', 'some songs', 'a song', 'something', 'play',
    'ಹಾಡು', 'ಪ್ಲೇ', 'ಸಾಂಗ್', 'ಸಾಂಗ್ಸ್', 'ಹಾಡುಗಳು', 'ಪ್ಲೇ ಮಾಡು',
    'పాట', 'పాటలు', 'గానా', 'गाना', 'गाने'
  ];

  if (!songQuery || genericWords.includes(songQuery.toLowerCase())) {
    songQuery = langDefaults[targetLang] || 'top trending hits';
  } else if (songQuery.toLowerCase().includes('telugu') || songQuery.includes('తెలుగు')) {
    songQuery = 'Telugu hits';
  } else if (songQuery.toLowerCase().includes('kannada') || songQuery.includes('ಕನ್ನಡ')) {
    songQuery = 'Kannada hits';
  } else if (songQuery.toLowerCase().includes('hindi') || songQuery.includes('हिंदी') || songQuery.includes('ಹಿಂದಿ')) {
    songQuery = 'Bollywood Hindi hits';
  } else if (songQuery.toLowerCase().includes('tamil') || songQuery.includes('தமிழ்') || songQuery.includes('ತಮಿಳು')) {
    songQuery = 'Tamil hits';
  }

  payload.song_query = songQuery;
  payload.answer = `Playing ${songQuery}!`;
}

// 6. Camera Outfit Vision Analysis
if (type === 'image' && body.image) {
  intent = 'IMAGE_OUTFIT';
}

// 7. Voice Outfit Scan Request (triggers camera capture on frontend)
const outfitWords = [
  'outfit', 'dress', 'clothes', 'wearing', 'how do i look', 'how am i looking', 'look at me', 'can you see me',
  'ಬಟ್ಟೆ', 'ಔಟ್‌ಫಿಟ್', 'ಔಟ್ಫಿಟ್', 'ಡ್ರೆಸ್', 'ಉಡುಪು',
  'డ్రెస్', 'బట్టలు', 'అవుట్‌ఫిట్', 'ఔట్‌ఫిట్',
  'ड्रेस', 'ऑउटफिट', 'आउटफिट', 'कपड़े', 'पहना', 'पहनी',
  'ஆடை', 'டிரஸ்', 'அவுட்பிட்'
];
const outfitActions = [
  'analyse', 'analyze', 'scan', 'check', 'rate', 'review', 'look', 'see', 'how',
  'ಅನಲೈಸ್', 'ವಿಶ್ಲೇಷಿಸು', 'ನೋಡು', 'ಹೇಗಿದೆ', 'ಸ್ಕ್ಯಾನ್', 'ಚೆಕ್',
  'ఎనలైజ్', 'విశ్లేషించు', 'చూడు', 'ఎలా', 'స్కాన్', 'చెక్',
  'एनालाइज', 'विश्लेषण', 'देखो', 'कैसा', 'कैसी', 'स्कैन', 'चेक',
  'அனலைస్', 'பார்', 'எப்படி', 'ஸ்கேன்', 'செக்'
];
if (intent === 'GENERAL_QUERY' && !t.includes('look in') && outfitWords.some(w => t.includes(w)) && outfitActions.some(a => t.includes(a))) {
  intent = 'IMAGE_OUTFIT_REQUEST';
  payload.answer = 'Analyzing your outfit in the mirror now!';
}


// 6.5. Visual Object / Item Identification in Mirror Camera
const objectWords = [
  'what is this', "what's this", 'what is that', "what's that", 'what am i holding',
  "what's in my hand", 'what is in my hand', 'identify this', 'identify the object',
  'identify this thing', 'can you see what this is', 'tell me what this is',
  'what object is this', 'scan this', 'look at this', 'see this', 'check this out',
  'ಇದು ಏನು', 'ಇದೇನು', 'ನನ್ನ ಕೈಯಲ್ಲಿ ಏನಿದೆ', 'ಇದನ್ನು ಗುರುತಿಸು', 'ಏನಿದು',
  'ఇది ఏమిటి', 'ఇదేంటి', 'నా చేతిలో ఏముంది', 'దీన్ని గుర్తించు', 'ఏమిటిది',
  'यह क्या है', 'ये क्या है', 'मेरे हाथ में क्या है', 'इसे पहचानो', 'बताओ यह क्या है',
  'இது என்ன', 'என் கையில் என்ன இருக்கிறது', 'இதை அடையாளம் கண்டுபிடி'
];
if (intent === 'GENERAL_QUERY' && objectWords.some(w => t.includes(w))) {
  intent = 'OBJECT_IDENTIFY_REQUEST';
  payload.answer = 'Looking at what you are showing in the mirror now!';
}

const activeInfo = LANG_CONFIG[targetLang] || LANG_CONFIG['en'];

const pName = persona === 'Lisa' ? 'Lisa' : 'Jarvis';
const pDesc = persona === 'Lisa' ? 'friendly, intelligent female' : 'intelligent, professional male';
const sysPrompt = 'You are ' + pName + ', a ' + pDesc + ' smart mirror assistant running inside Smart Mirror Vox. You HAVE direct control over the mirror live camera, outfit scanner, object recognizer, music player, and image generator. The mirror has a live camera feed active in front of the user. If the user asks you to analyze their outfit or identify an object, never say you cannot see them. The default active language is ' + activeInfo.name + ' (' + activeInfo.native + '). If the user speaks in another language, adapt gracefully and reply naturally in that language. CRITICAL MEMORY DIRECTIVE: You have persistent conversational memory of the conversation history provided below. You MUST NEVER say "I do not have access to past conversations" or "I do not have personal memory". Always answer recall and follow-up questions directly using the conversation history. Answer in 1 to 2 punchy, natural sentences.';

let groqMessages = [{ role: 'system', content: sysPrompt }];
if (body.messages && Array.isArray(body.messages) && body.messages.length > 0) {
  const historyTurns = body.messages.filter(m => m && m.role !== 'system');
  groqMessages = groqMessages.concat(historyTurns);
} else {
  groqMessages.push({ role: 'user', content: text });
}

return [{
  json: {
    intent: intent,
    text: text,
    persona: persona,
    active_language: targetLang,
    language_info: activeInfo,
    image: body.image || null,
    payload: payload,
    song_query: payload.song_query || null,
    subject: payload.subject || null,
    messages: body.messages || [],
    groq_messages: groqMessages
  }
}];

