={{ JSON.stringify({
  model: 'qwen/qwen3.8-27b',
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'image_url',
          image_url: {
            url: 'data:image/jpeg;base64,' + $json.image
          }
        },
        {
          type: 'text',
          text: 'Analyze this outfit in 2 sentences in ' + $json.language_info.name + '. Suggest 1 improvement.'
        }
      ]
    }
  ],
  max_tokens: 200
}) }}

={{ JSON.stringify({
  model: 'qwen/qwen3.8-27b',
  messages: $json.groq_messages || [{ role: 'user', content: $json.text }],
  temperature: 0.3,
  max_tokens: 160
}) }}
